@testable import Domain
import Testing

// T1.1 — ConsentGate protocol RED tests
// RED trigger: ConsentGate does not exist yet — compile fails until declared.

private struct AlwaysDeniedGate: ConsentGate {
    var isConsentGranted: Bool {
        false
    }
}

private struct AlwaysGrantedGate: ConsentGate {
    var isConsentGranted: Bool {
        true
    }
}

@Suite("ConsentGate")
struct ConsentGateTests {
    @Test func deniedGateReturnsFalse() async {
        let gate = AlwaysDeniedGate()
        #expect(await gate.isConsentGranted == false)
    }

    @Test func grantedGateReturnsTrue() async {
        let gate = AlwaysGrantedGate()
        #expect(await gate.isConsentGranted == true)
    }

    @Test func protocolIsSendable() {
        let _: any ConsentGate & Sendable = AlwaysDeniedGate()
        #expect(Bool(true))
    }
}

