import Domain
import SwiftUI

/// Four-step first-launch onboarding: local-first explainer → mic permission → system audio → calendar.
@MainActor
public struct OnboardingView: View {
    public let onComplete: () -> Void

    @State private var step = 0
    @State var vm: OnboardingViewModel

    public init(permissionService: any PermissionService, onComplete: @escaping () -> Void) {
        self.onComplete = onComplete
        _vm = State(initialValue: OnboardingViewModel(service: permissionService))
    }

    public var body: some View {
        VStack(spacing: 32) {
            Spacer()
            stepContent
            Spacer()
            navigationButtons
        }
        .padding(40)
        .frame(width: 520, height: 420)
        .task {
            await vm.refresh()
            if vm.allPermissionsGranted {
                vm.completeOnboarding()
                onComplete()
            }
        }
        .accessibilityLabel("Onboarding")
    }

    // MARK: - Steps

    @ViewBuilder
    var stepContent: some View {
        switch step {
        case 0: welcomeStep
        case 1: micStep
        case 2: audioStep
        case 3: calendarStep
        default: calendarStep
        }
    }

    // MARK: - Navigation

    var navigationButtons: some View {
        HStack {
            if step < 3 {
                Button(String(localized: "Skip")) { onComplete() }
                    .foregroundStyle(.secondary)
            }
            Spacer()
            if step == 3 {
                Button(String(localized: "Get Started")) {
                    vm.completeOnboarding()

        guard let json = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            Issue.record("Localizable.xcstrings is not a JSON object")
            return
        }
        let sourceLanguage = json["sourceLanguage"] as? String
        #expect(
            sourceLanguage == "en",
            "Localizable.xcstrings must declare sourceLanguage = 'en', got: \(sourceLanguage ?? "nil")"
        )
    }

    /// AC-1d: The catalog must contain at least one string entry.
    /// RED: fails because the file doesn't exist yet.
    @Test("AC-1d Localizable.xcstrings contains at least one string entry")
    func xcstringsCatalogHasEntries() throws {
        let xcstringsURL = presentationRoot
            .appendingPathComponent("Sources/Presentation/Localizable.xcstrings")
        let data = try Data(contentsOf: xcstringsURL)
        guard let json = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            Issue.record("Localizable.xcstrings is not a JSON object")
            return
        }
        let strings = json["strings"] as? [String: Any]
        let count = strings?.count ?? 0
        #expect(
            count > 0,
            "Localizable.xcstrings must contain at least one string entry — found 0 (REQ-F1, #121)"
        )
    }
}

// MARK: - AC-2: User-facing strings use String(localized:) or LocalizedStringKey

@Suite("task-007 Localization — AC-2: No hardcoded UI strings in target views")
struct HardcodedUIStringTests {

    /// AC-2a: MenuBarPopover must have no hardcoded Text/Button/Label string literals.
    /// RED: fails because "Record", "Stop", "Processing…", "Re-transcribe from Audio",
    ///      "Diarizing...", "Open Settings", "Show Window", "Quit" are all hardcoded.
    @Test("AC-2a MenuBarPopover — no hardcoded Text/Button literals")
    func menuBarPopoverNoHardcodedStrings() throws {
        let source = try presentationSource("Views/MenuBarPopover.swift")
        let violations = hardcodedUIStringViolations(in: source, fileName: "MenuBarPopover.swift")
        #expect(
            violations.isEmpty,
            """
            MenuBarPopover.swift has \(violations.count) hardcoded UI string(s). \
            Replace with String(localized:) or LocalizedStringKey (REQ-F1, #121):
            \(violations.joined(separator: "\n"))
            """
        )
    }

    /// AC-2b: OnboardingView must have no hardcoded Text/Button/Label string literals.
    /// RED: fails because "Your meetings stay on your Mac", "Microphone access",
    ///      "Allow Microphone Access", "System audio capture", "Skip", "Get Started",
    ///      "Continue" are all hardcoded.
    @Test("AC-2b OnboardingView — no hardcoded Text/Button literals")
    func onboardingViewNoHardcodedStrings() throws {
        let source = try presentationSource("Views/OnboardingView.swift")
        let violations = hardcodedUIStringViolations(in: source, fileName: "OnboardingView.swift")
        #expect(
            violations.isEmpty,
            """
            OnboardingView.swift has \(violations.count) hardcoded UI string(s). \
            Replace with String(localized:) or LocalizedStringKey (REQ-F1, #121):
            \(violations.joined(separator: "\n"))
            """
        )
    }

    /// AC-2c: MainWindowView must have no hardcoded Text/Button/Label string literals.
    /// RED: fails because "Select a meeting" and "Context suggestions unavailable" are hardcoded.
    @Test("AC-2c MainWindowView — no hardcoded Text/Button literals")
    func mainWindowViewNoHardcodedStrings() throws {
        let source = try presentationSource("Views/MainWindowView.swift")
        let violations = hardcodedUIStringViolations(in: source, fileName: "MainWindowView.swift")
        #expect(
            violations.isEmpty,
            """
            MainWindowView.swift has \(violations.count) hardcoded UI string(s). \
            Replace with String(localized:) or LocalizedStringKey (REQ-F1, #121):
            \(violations.joined(separator: "\n"))
            """
        )
    }

    /// AC-2d: SettingsView must have no hardcoded Label/Text string literals.
    /// RED: fails because "General", "Transcription", "Speakers", "Export", "Cache",
    ///      "Integrations", "Models", "About" are hardcoded Label titles.
    @Test("AC-2d SettingsView — no hardcoded Label literals")
    func settingsViewNoHardcodedStrings() throws {
        let source = try presentationSource("Views/SettingsView.swift")
        let violations = hardcodedUIStringViolations(in: source, fileName: "SettingsView.swift")
        #expect(
            violations.isEmpty,
            """
            SettingsView.swift has \(violations.count) hardcoded UI string(s). \
            Replace with String(localized:) or LocalizedStringKey (REQ-F1, #121):
            \(violations.joined(separator: "\n"))
            """
        )
    }
}

// MARK: - AC-3: Non-user-facing strings must NOT be localized

@Suite("task-007 Localization — AC-3: Logger strings are not localized")
struct LoggerStringNotLocalizedTests {

            path: "Sources/Logging",
            swiftSettings: sharedSwiftSettings
        ),
        .target(
            name: "Utilities",
            dependencies: ["Domain", "Logging"],
            path: "Sources/Utilities",
            swiftSettings: sharedSwiftSettings
        ),
        .testTarget(
            name: "DomainTests",
            dependencies: ["Domain", "Logging"],
            path: "Tests/Unit/Domain",
            exclude: [
                // T1.1 RED-by-design: references ConsentGate, which was never
                // implemented. Left included it breaks compilation of every
                // test target in this package. See issue #290.
                "ConsentGateTests.swift",
            ]
        ),
        .testTarget(
            name: "UtilitiesTests",
            dependencies: ["Utilities"],
            path: "Tests/Unit/Utilities"
        ),
    ]
)

