import Domain
import Foundation
import Logging
import Observation

private let logger = AppLogger.for(category: "LiveTranscriptionVM")

@Observable
@MainActor
public final class LiveTranscriptionViewModel {
    public var segments: [StreamingSegment] = []
    public var meetingId: RecordingID?

    /// Called once per batch flush with the last segment in the batch.
    /// Wired by `BroadsheetAppState` to update `liveTranscriptTurns`.
    public var onSegmentsAppended: (([StreamingSegment]) -> Void)?

    @ObservationIgnored private var pendingSegments: [StreamingSegment] = []
    @ObservationIgnored private var batchTask: Task<Void, Never>?
    @ObservationIgnored private let batchInterval: Duration = .milliseconds(100)

    public init() {}

    public func appendSegment(_ segment: StreamingSegment) {
        pendingSegments.append(segment)

        batchTask?.cancel()
        batchTask = Task { [weak self, batchInterval] in
            do {
                try await Task.sleep(for: batchInterval)
            } catch {
                return // cancelled — a newer batch timer replaced this one
            }
            self?.flushPendingSegments()
        }
    }

    private func flushPendingSegments() {
        guard !pendingSegments.isEmpty else { return }
        let batch = pendingSegments
        pendingSegments.removeAll()

        if batch.count > 5 {
            logger.debug("Flushing batch of \(batch.count, privacy: .public) segments")
        }

        // Single array mutation — one @Observable invalidation
        segments.append(contentsOf: batch)
        segments.sort { $0.timestamp < $1.timestamp }

        if segments.count > 1000 {
            segments.removeFirst(segments.count - 1000)
        }

        // Callback for the batch
        if !batch.isEmpty {
            onSegmentsAppended?(batch)
        }
    }

    public func flushForTesting() {
        batchTask?.cancel()
        flushPendingSegments()
    }

    public func clear() {
        batchTask?.cancel()
        batchTask = nil
        pendingSegments.removeAll()
        segments.removeAll()
        // meetingId intentionally preserved — set before clear() in startLiveStream
    }
}

