import Testing
import Foundation
@testable import Business
import Domain
import StorageInfrastructure

/// Integration test for the full context-query chain (Wave 5 mega-remediation E6).
///
/// Exercises real infrastructure end to end: a real `ObsidianProvider` reading
/// markdown files from a temp vault directory, wrapped in a real
/// `CachingContextProvider` backed by a real `GRDBContextCache` at a temp
/// SQLite path, driven through the real `QueryContextUseCase`. No mocks.
///
/// Gated behind RUN_INTEGRATION_TESTS=1 so it never runs in the default unit
/// suite / CI — it touches the real filesystem and a real SQLite database.
///
/// Run with:
///   RUN_INTEGRATION_TESTS=1 swift test --filter "QueryContextUseCaseIntegration"
private let integrationEnabled = ProcessInfo.processInfo.environment["RUN_INTEGRATION_TESTS"] == "1"

@Suite("QueryContextUseCase integration (E6)", .serialized)
struct QueryContextUseCaseIntegrationTests {

    // MARK: - Helpers

    /// Creates a temp vault directory with a few markdown notes and returns its URL.
    private func makeTempVault() throws -> URL {
        let dir = FileManager.default.temporaryDirectory
            .appendingPathComponent("query-context-integration-vault-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)

        try "# Kubernetes Notes\nPod scheduling and the kube-scheduler control loop."
            .write(to: dir.appendingPathComponent("k8s-notes.md"), atomically: true, encoding: .utf8)
        try "# Lambda Architecture\nEvent-driven serverless compute patterns."
            .write(to: dir.appendingPathComponent("lambda-notes.md"), atomically: true, encoding: .utf8)
        try "# Standup 2026-06-30\nDiscussed Kubernetes rollout timeline for the platform team."
            .write(to: dir.appendingPathComponent("standup.md"), atomically: true, encoding: .utf8)

        return dir
    }

    /// Returns a temp SQLite database path (file does not yet exist — GRDB creates it).
    private func makeTempDatabasePath() -> URL {
        FileManager.default.temporaryDirectory
            .appendingPathComponent("query-context-integration-cache-\(UUID().uuidString).sqlite")
    }

    // MARK: - AC-E6: full chain, second identical query is served from cache

    @Test(
        "E6: ObsidianProvider -> CachingContextProvider -> QueryContextUseCase, second query is a cache hit",
        .enabled(if: integrationEnabled, "Set RUN_INTEGRATION_TESTS=1 to run this test")
    )
    func fullChainSecondQueryIsCacheHit() async throws {
        let vault = try makeTempVault()
        let dbPath = makeTempDatabasePath()
        defer {
            try? FileManager.default.removeItem(at: vault)
            try? FileManager.default.removeItem(at: dbPath)
        }

        let obsidian = ObsidianProvider(vaultPath: vault)
        let cache = try GRDBContextCache(databasePath: dbPath)
        let cachingProvider = CachingContextProvider(inner: obsidian, cache: cache)
        let useCase = QueryContextUseCase(mcpConsentGranted: true)

        // Entry count starts at zero for a fresh database.
        let entriesBeforeFirst = try await cache.entryCount(providerID: obsidian.providerID.rawValue)
        #expect(entriesBeforeFirst == 0, "Fresh cache must start empty")

        // First query: cache miss — must read through to ObsidianProvider and populate the cache.
        let firstSuggestions = await useCase.query(text: "Kubernetes", providers: [cachingProvider])
        #expect(firstSuggestions.count >= 1, "First query must surface results from ObsidianProvider")
        #expect(
            firstSuggestions.contains { $0.title.lowercased().contains("k8s-notes") || $0.body.lowercased().contains("kubernetes") },
            "Expected a Kubernetes-related suggestion from the temp vault"
        )

        let entriesAfterFirst = try await cache.entryCount(providerID: obsidian.providerID.rawValue)
        #expect(
            entriesAfterFirst > entriesBeforeFirst,
            "The first (miss) query must write at least one cache entry (one row per cached result)"
        )

        // Second identical query, through the full use case again: must be served from cache.
        let secondSuggestions = await useCase.query(text: "Kubernetes", providers: [cachingProvider])
        let entriesAfterSecond = try await cache.entryCount(providerID: obsidian.providerID.rawValue)

        #expect(
            entriesAfterSecond == entriesAfterFirst,
            "Cache entry count must not change on cache hit — second query must be served from cache, not the provider"
        )
        #expect(
            secondSuggestions.map(\.title).sorted() == firstSuggestions.map(\.title).sorted(),
            "Second (cached) query must return the same suggestions as the first"
        )
        #expect(
            secondSuggestions.map(\.sourceProvider) == firstSuggestions.map(\.sourceProvider),
            "Cached suggestions must retain the original source provider"
        )
    }
}

