import Foundation
import Testing

/// Source-inspection ratchet for #109: the ASR and diarization plugins must
/// carry OSSignpost intervals so Instruments can visualize model load,
/// warm-up, and inference stages.
///
/// Signpost emission has no observable side effect a unit test can assert on
/// (it goes straight to the os_signpost buffer), so this ratchet pins the
/// instrumentation in source the same way the AppAssembler wiring tests do.
/// The signposter must come from `AppLogger.signposter` — subsystem
/// "app.the-record" is the SSOT; never construct OSSignposter with an inline
/// subsystem string.
@Suite("Plugin signpost instrumentation ratchet (#109)")
struct PluginSignpostRatchetTests {
    private static func pluginSource(_ relativePath: String) -> String {
        let thisFile = URL(fileURLWithPath: #filePath)
        let sourceURL = thisFile
            .deletingLastPathComponent() // Unit/
            .deletingLastPathComponent() // Tests/
            .deletingLastPathComponent() // Record-ML (package root)
            .appendingPathComponent("Sources/MLInfrastructure/\(relativePath)")
        return (try? String(contentsOf: sourceURL, encoding: .utf8)) ?? ""
    }

    private static let whisperSource = pluginSource("Transcription/WhisperKitPlugin.swift")
    private static let diarizationSource = pluginSource("Diarization/OfflineDiarizationPlugin.swift")

    @Test("WhisperKitPlugin uses the AppLogger Performance signposter")
    func whisperUsesAppLoggerSignposter() {
        #expect(Self.whisperSource.contains(#"AppLogger.signposter(category: "Performance")"#))
    }

    @Test("WhisperKitPlugin marks loadModel, warmup, and per-chunk transcription intervals")
    func whisperIntervals() {
        #expect(Self.whisperSource.contains(#"beginInterval("loadModel""#))
        #expect(Self.whisperSource.contains(#"beginInterval("warmupModels""#))
        #expect(Self.whisperSource.contains(#"beginInterval("transcribeChunk""#))
    }

    @Test("OfflineDiarizationPlugin uses the AppLogger Performance signposter")
    func diarizationUsesAppLoggerSignposter() {
        #expect(Self.diarizationSource.contains(#"AppLogger.signposter(category: "Performance")"#))
    }

    @Test("OfflineDiarizationPlugin marks model-prepare and full-job intervals")
    func diarizationIntervals() {
        #expect(Self.diarizationSource.contains(#"beginInterval("loadModel""#))
        #expect(Self.diarizationSource.contains(#"beginInterval("diarizationJob""#))
    }
}

